import { readFileSync } from 'node:fs'

import type { Client } from 'pg'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { adminUpdateOrg } from '@/core/org'
import { REF_CODE_PATTERN } from '@/core/org/ref-code'

import { connectAdmin, serviceClient } from './helpers'
import { adminAccount, orgWith } from './org-fixtures'

// orgs.ref_code (1801, ARCHITECTURE §6.5): the enterprise number for bank-transfer references.
// Generated by the database on insert, backfilled for older orgs, unique, never changes, and only
// readable by the service role (the owner and admins see it through the server). Fake data only.

const service = serviceClient()
let db: Client
let actor: string

beforeAll(async () => {
  db = await connectAdmin()
  actor = await adminAccount(db, service)
})
afterAll(async () => { await db.end() })

const codeOf = async (orgId: string) => (await db.query('select ref_code from public.orgs where id = $1', [orgId])).rows[0].ref_code as string

describe('generation', () => {
  it('gives every new org its own SV- number in the unambiguous alphabet', async () => {
    const orgs = await Promise.all([orgWith(db, service, actor), orgWith(db, service, actor), orgWith(db, service, actor)])
    const codes = await Promise.all(orgs.map((o) => codeOf(o.orgId)))
    for (const code of codes) expect(code).toMatch(REF_CODE_PATTERN)
    expect(new Set(codes).size).toBe(3)
  })

  it('never hands out a code that is already taken', async () => {
    const taken = new Set((await db.query('select ref_code from public.orgs')).rows.map((r) => r.ref_code as string))
    const fresh = new Set<string>()
    for (let i = 0; i < 200; i++) {
      const code = (await db.query('select public._org_ref_code_new() as code')).rows[0].code as string
      expect(code).toMatch(REF_CODE_PATTERN)
      expect(taken.has(code)).toBe(false)
      fresh.add(code)
    }
    expect(fresh.size).toBeGreaterThan(190)
  })
})

describe('backfill, uniqueness and format', () => {
  it('fills every org that has none, with distinct valid codes, using the migration statement itself', async () => {
    await orgWith(db, service, actor)
    await orgWith(db, service, actor)
    const sql = readFileSync('supabase/migrations/1801_org_ref_code.sql', 'utf8')
    const backfill = sql.slice(sql.indexOf('do $$'), sql.indexOf('end $$;') + 'end $$;'.length)
    expect(backfill).toContain('update public.orgs set ref_code')
    await db.query('begin')
    try {
      await db.query('alter table public.orgs disable trigger orgs_ref_code_guard')
      await db.query('update public.orgs set ref_code = null')
      await db.query(backfill)
      await db.query('alter table public.orgs enable trigger orgs_ref_code_guard')
      const { rows } = await db.query('select count(*)::int as n, count(distinct ref_code)::int as d, bool_and(ref_code ~ $1) as ok from public.orgs', [REF_CODE_PATTERN.source])
      expect(rows[0].ok).toBe(true)
      expect(rows[0].n).toBe(rows[0].d)
      expect(rows[0].n).toBeGreaterThanOrEqual(2)
    } finally {
      await db.query('rollback')
    }
  })

  it('refuses a duplicate and a malformed number (with the guard trigger off, so only the constraints speak)', async () => {
    const a = await orgWith(db, service, actor)
    const b = await orgWith(db, service, actor)
    const attempt = async (code: string) => {
      await db.query('begin')
      try {
        await db.query('alter table public.orgs disable trigger orgs_ref_code_guard')
        await db.query('update public.orgs set ref_code = $1 where id = $2', [code, b.orgId])
      } finally {
        await db.query('rollback')
      }
    }
    await expect(attempt(await codeOf(a.orgId))).rejects.toThrow('orgs_ref_code_key')
    for (const bad of ['SV-ABC0EF', 'SV-ABCDEI', 'sv-abcdef', 'SV-ABCDE', 'XX-ABCDEF']) {
      await expect(attempt(bad)).rejects.toThrow('orgs_ref_code_format')
    }
  })
})

describe('immutability', () => {
  it('rejects any change to the number and lets every other edit through', async () => {
    const { orgId } = await orgWith(db, service, actor)
    const before = await codeOf(orgId)
    await expect(db.query('update public.orgs set ref_code = $1 where id = $2', ['SV-ZZZZZZ', orgId])).rejects.toThrow('ORG_REF_CODE_IMMUTABLE')
    await expect(db.query('update public.orgs set ref_code = null where id = $1', [orgId])).rejects.toThrow('ORG_REF_CODE_IMMUTABLE')
    await adminUpdateOrg(service, actor, orgId, { name: 'Renamed Test Org', status: 'suspended', rotate_invite: true })
    await db.query('update public.orgs set pool_credits = pool_credits + 1 where id = $1', [orgId])
    expect(await codeOf(orgId)).toBe(before)
  })
})

describe('privileges', () => {
  it('keeps the column and both helper functions away from clients', async () => {
    const { orgId } = await orgWith(db, service, actor)
    for (const role of ['anon', 'authenticated']) {
      await db.query('begin')
      await db.query(`set local role ${role}`)
      await expect(db.query('select ref_code from public.orgs where id = $1', [orgId])).rejects.toThrow('permission denied')
      await db.query('rollback')
    }
    for (const fn of ['public._org_ref_code_new()', 'public._orgs_ref_code_guard()']) {
      for (const role of ['anon', 'authenticated', 'service_role']) {
        const { rows } = await db.query('select has_function_privilege($1, $2, $3) as ok', [role, fn, 'execute'])
        expect(rows[0].ok).toBe(false)
      }
    }
    const read = await service.select(`orgs?select=ref_code&id=eq.${orgId}`)
    expect(await read.json()).toEqual([{ ref_code: await codeOf(orgId) }])
  })
})
